from fractions import Fraction

def show(M):
    for row in M:
        cells = [f"{str(x):>6}" for x in row]
        print("  [" + " ".join(cells[:-1]) + " |" + cells[-1] + " ]")

def coef(c):
    if c == 1:
        return ""
    return str(c) if c.denominator == 1 else f"({c})"

def name(op):
    if op[0] == "swap":
        return f"R{op[1]} ↔ R{op[2]}"
    if op[0] == "scale":
        return f"R{op[1]} → {coef(op[2])}R{op[1]}"
    i, j, c = op[1], op[2], op[3]
    sign = "-" if c < 0 else "+"
    return f"R{i} → R{i} {sign} {coef(abs(c))}R{j}"

def swap(M, i, j):
    M[i], M[j] = M[j], M[i]

def scale(M, i, c):
    M[i] = [c * x for x in M[i]]

def replace(M, i, j, c):
    M[i] = [M[i][k] + c * M[j][k] for k in range(len(M[i]))]

def do(M, op):
    if op[0] == "scale" and op[2] == 0:
        print(f"{name(op)}: not allowed, scaling by 0 can't be undone")
        return
    if op[0] == "swap":
        swap(M, op[1] - 1, op[2] - 1)
    elif op[0] == "scale":
        scale(M, op[1] - 1, op[2])
    else:
        replace(M, op[1] - 1, op[2] - 1, op[3])
    print(name(op))
    show(M)

def run(label, rows, ops):
    M = [[Fraction(x) for x in row] for row in rows]
    print(label)
    show(M)
    for op in ops:
        do(M, op)

F = Fraction
run("Case 1 · Example 5: x + 2y = 5, 3x + 4y = 6", [[1, 2, 5], [3, 4, 6]],
    [("replace", 2, 1, F(-3)), ("scale", 2, F(-1, 2)), ("replace", 1, 2, F(-2))])
run("Case 2 · a swap first: 2y = 4, 3x + y = 5", [[0, 2, 4], [3, 1, 5]],
    [("swap", 1, 2), ("scale", 2, F(1, 2)), ("replace", 1, 2, F(-1)), ("scale", 1, F(1, 3))])
run("Case 3 · the tickets", [[1, 1, 7], [12, 5, 63]],
    [("replace", 2, 1, F(-12)), ("scale", 2, F(-1, 7)), ("replace", 1, 2, F(-1))])
run("Case 4 · the trap", [[1, 1, 3], [1, -1, 1]], [("scale", 2, F(0))])

