from fractions import Fraction
import numpy as np

def show(M):
    for row in M:
        cells = [f"{str(x):>6}" for x in row]
        print("  [" + " ".join(cells[:-1]) + " |" + cells[-1] + " ]")

def coef(c):
    if c == 1:
        return ""
    return str(c) if c.denominator == 1 else f"({c})"

def name(op):
    if op[0] == "swap":
        return f"R{op[1]} ↔ R{op[2]}"
    if op[0] == "scale":
        return f"R{op[1]} → {coef(op[2])}R{op[1]}"
    i, j, c = op[1], op[2], op[3]
    sign = "-" if c < 0 else "+"
    return f"R{i} → R{i} {sign} {coef(abs(c))}R{j}"

def swap(M, i, j):
    M[i], M[j] = M[j], M[i]

def scale(M, i, c):
    M[i] = [c * x for x in M[i]]

def replace(M, i, j, c):
    M[i] = [M[i][k] + c * M[j][k] for k in range(len(M[i]))]

def eliminate(M):
    n = len(M)
    for c in range(n):
        p = c
        while M[p][c] == 0:
            p += 1
        if p != c:
            swap(M, c, p)
            print(f"R{c + 1} ↔ R{p + 1}")
            show(M)
        for i in range(c + 1, n):
            if M[i][c] != 0:
                m = M[i][c] / M[c][c]
                replace(M, i, c, -m)
                print(name(("replace", i + 1, c + 1, -m)))
                show(M)

def paren(x):
    if x < 0:
        return f"({x})"
    return str(x)

def back_substitute(M):
    n = len(M)
    x = [0] * n
    for i in range(n - 1, -1, -1):
        known = sum(M[i][j] * x[j] for j in range(i + 1, n))
        x[i] = (M[i][n] - known) / M[i][i]
        print(f"  x{i + 1} = ({M[i][n]} - {paren(known)}) / {paren(M[i][i])} = {x[i]}")
    return x

def solve(label, rows):
    M = [[Fraction(x) for x in row] for row in rows]
    n = len(M)
    print(label)
    show(M)
    eliminate(M)
    print("  back substitution:")
    x = back_substitute(M)
    A = [row[:n] for row in rows]
    b = [row[n] for row in rows]
    print(f"  numpy agrees: {np.allclose([float(v) for v in x], np.linalg.solve(A, b))}")

