solve("Case 2 · a swap needed", [[0, 1, 2, -1], [1, 1, 1, 2], [2, 1, 3, 2]])
solve("Case 3 · a fraction multiplier", [[2, 3, 1], [5, 4, 3]])
solve("Case 4 · the parabola", [[1, -1, 1, 6], [1, 1, 1, 2], [4, 2, 1, 3]])
solve("Case 5 · four unknowns", [[1, 1, 1, 1, 10], [1, -1, 2, 0, 5], [2, 1, 0, 1, 8], [0, 1, 1, -1, 1]])

