from fractions import Fraction

def show(M):
    for row in M:
        cells = [f"{str(x):>6}" for x in row]
        print("  [" + " ".join(cells[:-1]) + " |" + cells[-1] + " ]")

def reduce(M):
    rows, cols = len(M), len(M[0])
    r = 0
    for c in range(cols - 1):
        p = r
        while p < rows and M[p][c] == 0:
            p += 1
        if p == rows:
            continue
        M[r], M[p] = M[p], M[r]
        M[r] = [x / M[r][c] for x in M[r]]
        for i in range(rows):
            if i != r:
                a = M[i][c]
                M[i] = [M[i][k] - a * M[r][k] for k in range(cols)]
        r += 1
        if r == rows:
            break

def term(c, j):
    a = abs(c)
    if a == 1:
        a = ""
    elif a.denominator != 1:
        a = f"({a})"
    return (" - " if c < 0 else " + ") + str(a) + f"x{j + 1}"

def classify(M):
    n = len(M[0]) - 1
    for row in M:
        if all(x == 0 for x in row[:n]) and row[n] != 0:
            print(f"  a row says 0 = {row[n]}: inconsistent, no solution")
            return
    pivots = []
    for row in M:
        for j in range(n):
            if row[j] != 0:
                pivots.append(j)
                break
    free = [j for j in range(n) if j not in pivots]
    print("  pivot columns: " + ", ".join(str(j + 1) for j in pivots))
