def classify(M):
    n = len(M[0]) - 1
    for row in M:
        if all(x == 0 for x in row[:n]) and row[n] != 0:
            print(f"  a row says 0 = {row[n]}: inconsistent, no solution")
            return
    pivots = []
    for row in M:
        for j in range(n):
            if row[j] != 0:
                pivots.append(j)
                break
    free = [j for j in range(n) if j not in pivots]
    print("  pivot columns: " + ", ".join(str(j + 1) for j in pivots))
    if len(free) == 0:
        print("  no free variables, one solution: "
              + ", ".join(f"x{pivots[i] + 1} = {M[i][n]}" for i in range(len(pivots))))
        return
    print("  free: " + ", ".join(f"x{j + 1}" for j in free) + ", infinitely many solutions")
    for i in range(len(pivots)):
        text = f"x{pivots[i] + 1} = {M[i][n]}"
        for j in free:
            if M[i][j] != 0:
                text += term(-M[i][j], j)
        print("  " + text)

